import sys, math, json, re
import pandas as pd
from collections import defaultdict
from zoneinfo import ZoneInfo
from datetime import timedelta
week = sys.argv[1]; outdir = sys.argv[2] if len(sys.argv) > 2 else "/app/out/litware"
tz = ZoneInfo("Europe/London")
def erl_req(vol, aht, tgt, sec, cap=0.85, T=1200):
    a = vol/T*aht
    if a <= 0: return 0
    n = max(1, math.ceil(a))
    while True:
        if a/n <= cap and n > a:
            term = 1.0; s = 1.0
            for k in range(1, n):
                term *= a/k; s += term
            term *= a/n; top = term*n/(n-a); pw = top/(s+top)
            if 1 - pw*math.exp(-(n-a)*sec/aht) >= tgt: return n
        n += 1
SLA = {"priority": (.9, 30), "standard": (.8, 30), "email": (.8, 300)}
df = pd.read_csv(f"/app/data/litware/export_{week}.csv")
end = pd.to_datetime(df.interval_end_local.str.strip() + df.utc_offset.str.strip(), format="%Y-%m-%d %H:%M%z", utc=True)
df["t"] = end - pd.Timedelta(minutes=20)
df["req"] = [erl_req(v, a, *SLA[q]) for v, a, q in zip(df.volume, df.aht_sec, df.queue)]
grid = sorted(df.t.unique()); grid = [pd.Timestamp(g) for g in grid]
req = {q: dict(zip(g.t, g.req)) for q, g in df.groupby("queue")}
vol = {q: dict(zip(g.t, g.volume)) for q, g in df.groupby("queue")}
sch = pd.read_csv(f"{outdir}/schedule.csv", parse_dates=["segment_start_utc", "segment_end_utc", "break_start_utc"])
sch["s"] = pd.to_datetime(sch.segment_start_utc, utc=True); sch["e"] = pd.to_datetime(sch.segment_end_utc, utc=True)
sch["b"] = pd.to_datetime(sch.break_start_utc, utc=True)
ag = pd.read_csv("/app/data/agents/litware.csv").set_index("agent_id")
viol = defaultdict(list)
def lh(t): l = t.astimezone(tz); return l.hour + l.minute/60
gross = {q: defaultdict(int) for q in SLA}; brk = {q: defaultdict(int) for q in SLA}
for r in sch.itertuples():
    for t in grid:
        if r.s <= t < r.e:
            gross[r.queue][t] += 1
            if r.break_minutes and r.b <= t < r.b + pd.Timedelta(minutes=20): brk[r.queue][t] += 1
# shifts per agent-local-day
sch["day"] = [x.astimezone(tz).date() for x in sch.s]
shifts = {}
for (a, d), g in sch.groupby(["agent_id", "day"]):
    shifts[(a, d)] = g.sort_values("s")
TPL = {"D8": [(9, 17)], "L8": [(13, 21)], "P6a": [(7, 13)], "P6b": [(15, 21)], "P4": [(10, 14)], "S44": [(8, 12), (16, 20)]}
for (a, d), g in shifts.items():
    if len(set(g.queue)) > 1: viol["multi-queue-day"].append((a, d))
    if g.template_id.nunique() != 1: viol["tpl-mix"].append((a, d))
    tid = g.template_id.iat[0]
    if tid not in TPL: viol["template"].append((a, d, tid)); continue
    segs = [(x.astimezone(tz).hour + x.astimezone(tz).minute/60, y.astimezone(tz).hour + y.astimezone(tz).minute/60 or 24) for x, y in zip(g.s, g.e)]
    if segs != TPL[tid]: viol["template-shape"].append((a, d, segs))
    contract = ag.loc[a, "contract"]
    if len(g) > 1 and contract != "PT": viol["split"].append((a, d))
    q = g.queue.iat[0]
    if q not in ag.loc[a, "skills"].split(";"): viol["skill"].append((a, d))
    if q == "email" and lh(g.s.iat[0]) < 9: viol["email<9"].append((a, d))
    hrs = sum((y - x).total_seconds() for x, y in zip(g.s, g.e))/3600
    start = g.s.iat[0]
    brs = g[g.break_minutes > 0]
    if hrs >= 6:
        if len(brs) != 1 or brs.break_minutes.iat[0] != 20: viol["break-count"].append((a, d)); continue
        b = brs.b.iat[0]
